quests[8691] = { id = 8691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuch der behüteten Geheimnisse", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Kampftuch der Qiraji, 2 Alabastergötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, {name}?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, {name}. Möge er Euch vor der üblen Magie der Qiraji schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8692] = { id = 8692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umhang des endlosen Lebens", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Hoheitstuch der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8693] = { id = 8693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umhang der Schattenschleier", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Kampftuch der Qiraji, 2 Azurgötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, {name}?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, {name}. Möge er Euch vor der üblen Magie der Qiraji schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8694] = { id = 8694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleier der ungesagten Namen", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Hoheitstuch der Qiraji, 2 Bernsteingötzen, 5 Elfenbeinskarabäen und 5 Bronzeskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8695] = { id = 8695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cape der ewigen Gerechtigkeit", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Hoheitstuch der Qiraji, 2 Obsidiangötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8696] = { id = 8696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umhang des unsichtbaren Pfads", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Hoheitstuch der Qiraji, 2 züngelnde Götzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, {name}?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, {name}. Möge er Euch vor der üblen Magie der Qiraji schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8697] = { id = 8697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der unendlichen Weisheit", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Zeremonienring der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8698] = { id = 8698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der aufziehenden Stürme", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8699] = { id = 8699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Band der behüteten Geheimnisse", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 Azurgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8700] = { id = 8700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Band des endlosen Lebens", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, <mein getreuer Druide/meine getreue Druidin>.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 Alabastergötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8701] = { id = 8701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Band der Schattenschleier", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Zeremonienring der Qiraji, 2 Onyxgötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8702] = { id = 8702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der ungesagten Namen", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Zeremonienring der Qiraji, 2 Jaspisgötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8703] = { id = 8703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der ewigen Gerechtigkeit", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8704] = { id = 8704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des unsichtbaren Pfads", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 Bernsteingötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8705] = { id = 8705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer der unendlichen Weisheit", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 verschnörkelten Griff der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
quests[8706] = { id = 8706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer der aufziehenden Stürme", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 Stachelgriff der Qiraji, 2 Bernsteingötzen, 5 Elfenbeinskarabäen und 5 Bronzeskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8707] = { id = 8707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge der behüteten Geheimnisse", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 verschnörkelten Griff der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8708] = { id = 8708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitkolben des endlosen Lebens", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 verschnörkelten Griff der Qiraji, 2 Jaspisgötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
quests[8709] = { id = 8709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolch der Schattenschleier", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 Stachelgriff der Qiraji, 2 Zinnobergötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
quests[8710] = { id = 8710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kris der ungesagten Namen", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 verschnörkelten Griff der Qiraji, 2 Onyxgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8711] = { id = 8711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge der ewigen Gerechtigkeit", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 Stachelgriff der Qiraji, 2 Bernsteingötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8712] = { id = 8712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sense des unsichtbaren Pfads", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 Stachelgriff der Qiraji, 2 Azurgötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
