quests[8728] = { id = 8728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gute und die schlechte Nachricht", description = "Das hat ein wenig länger gedauert als erwartet. Nun lasst mich sehen, was dieses Buch zu berichten hat.\n\n<Leise vor sich hermurmelnd beginnt Narain das Buch zu lesen.>\n\nDie gute Nachricht ist, dass ich mir zu 99% sicher bin, eine Arkanitboje konstruieren zu können, die voll und ganz Euren Anforderungen entspricht. Kommen wir zur schlechten Nachricht: Ich brauche eine gehörige Menge Arkanit, Elementiumerz und Edelsteine.\n\nSobald Ihr mir diese Materialien gebracht habt, kann ich mit der Konstruktion der Boje beginnen.", sourceObjective = "Narain Pfauentraum in Tanaris möchte, dass Ihr ihm 20 Arkanitbarren, 10 Elementiumerz, 10 Azerothische Diamanten und 10 blaue Saphire bringt.", progress = "Arkanitbojen bauen sich nicht einfach von selbst, {name}. Und NEIN, ich werde Euch kein Geld leihen.", completion = "Ein Abmachung ist eine Abmachung. {name}, Ich hoffe nur, Ihr wisst worauf Ihr Euch da einlasst. Das ist 'ne Menge Ärger, für 'nen kleinen Angelausflug.", sourceObjectiveStatus = "unverified-source-field" }
quests[8729] = { id = 8729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn von Neptulon", description = "Hatte ich die schlechte Neuigkeit schon zur Sprache gebracht? Sein Name ist \"Der weiße Riese\": Dreißig Meter Tod und Zerstörung pur. Den kleinen Leckerbissen hatte ich glatt vergessen.\n\nMeinen gnomischen Superpsychokräften nach zu urteilen, befindet sich der beste Ort, um diese Boje zu platzieren, an der Küste Azsharas in der Bucht der Stürme.\n\nHaltet nach einem wirbelnden Mahlstrom Ausschau. Vermutlich ist die ganze Gegend mit Wrackteilen übersät.\n\nMacht es gut und nehmt ein paar Freunde mit.\n\nFalls Ihr die ganze Sache wie durch ein Wunder überleben solltet, bringt den Szeptersplitter zu Anachronos.", sourceObjective = "Benutzt die Arkanitboje am wirbelnden Mahlstrom in der Bucht der Stürme in Azshara.", progress = "Die Zeit läuft uns davon, großer Held!", completion = "Gut gemacht, {name}. Schon bald werde ich das Szepter der Sandstürme wieder zusammensetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8730] = { id = 8730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nefarius' Verderbnis", description = "Held, seid Ihr es? Es ist tausend Jahre her, seitdem man mir den Splitter anvertraut hat. Jetzt, in meiner finstersten Stunde soll jemand erscheinen, um mich davon zu entlasten... aber was wäre eine Tragödie ohne Grausamkeit?\n\n<Vaelastrasz hustet geschwächt.>\n\nNe... Nefarius besitzt nun den Szeptersplitter.\n\nDie Zeit ist entscheidend. Nefarius hat vor den Splitter zu zerstören. Ihr müsst Euch beeilen!", sourceObjective = "Tötet Nefarian und bringt den roten Szeptersplitter wieder in Euren Besitz. Bringt den roten Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris. Euch bleiben 5 Stunden, um diese Aufgabe zu erfüllen.", progress = "Wir haben einen weiteren unserer Helden an die Brut von Deathwing verloren. Wir werden für immer zu diesem Leiden verdammt sein...", completion = "Vaelastrasz' Seele beruhigt sich, Held. Die Aspekte verfolgen Eure Fortschritte mit großem Interesse. Wisset, dass Ihr mächtige Verbündete habt.\n\nMir wurde aufgetragen Euch etwas zu geben, das Euch in diesem Kampf helfen soll. Verwendet es weise...", sourceObjectiveStatus = "unverified-source-field" }
quests[8731] = { id = 8731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felddienst", description = "Seid gegrüßt, {name}. Bevor ich Euch mit umfassenderen Aufgaben in diesem Krieg beauftrage, müsst Ihr Euren Anteil am Felddienst leisten.\n\nIhr könnt die Orgrimmarlegion von Hauptmann Schädelspalt außerhalb des Regalschwarmbaus finden.\n\nErstattet ihm Bericht und kommt mit dem Beweis für Euren Felddienst zu mir zurück. Ich werde wichtigere Anweisungen für Euch bereithalten.\n\nOh, bitte haltet Euch von der Eisenschmiedebrigade fern. Es herrschen große Spannungen zwischen unseren Freiwilligen der Allianz und der Horde.", sourceObjective = "Erstattet Krug Schädelspalt am Posten der Orgrimmarlegion beim Regalschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie unterzeichnen und bringt sie dann zu Windrufer Kaldon auf Burg Cenarius.\n\nHinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Orgrimmarlegion wird Euch für den PvP-Kampf markieren.", progress = "Ihr habt Euren Felddienst geleistet, {name}? Captain Skullsplit hält sich außerhalb des Regalschwarmbaus auf.", completion = "Ich sehe, dass Krug wenig Sinn für Papierkram hat. Er hat das mit Silithidenblut unterzeichtet!\n\nNun gut, {name}. Ich habe eine Reihe von Aufgaben vorbereitet, die Euren Fähigkeiten als {class} gerecht werden sollten.\n\nUnser Feind wird dank der anhaltenden Bemühungen von Euch und Euresgleichen bald zerschmettert werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[8732] = { id = 8732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felddienstpapiere", progress = "Felddienstpapiere? Was für ein Schwachsinn ist das, {name}?", completion = "Früher hätte ich Eure Stirn mit dem Blut unserer gefallenen Feinde gezeichnet, um Eure Taten kenntlich zu machen. Thrall besteht darauf, dass wir den Anliegen der Druiden nachkommen.\n\nHier, nehmt diese Papiere und geht zurück nach Burg Cenarius. Ich bin mir sicher, dass sie dort passende Aufgaben für Euch haben werden." }
quests[8733] = { id = 8733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus, der Tyrann des Traums", description = "Dies ist der Weg der Begleichung, Held. Würde ich heute getötet werden, dann würde ich für den gerechten Zweck sterben. Ihr müsst den grünen Szeptersplitter wiedererlangen. Ihr müsst Eranikus von der Besudelung, die die alten Götter über ihn verhängt haben, reinigen.\n\nReist nach Darnassus. Ihr werdet einen meiner Agenten genau vor den Stadtmauern finden. Dieser Agent wird die Dinge für uns in Bewegung setzen und Tyrande über unsere Pläne informieren, ohne Hirschhaupt zu alarmieren.\n\n<Malfurion seufzt.>\n\nEin Bruch mit der in tausend Jahren geschaffenen Gunst...", sourceObjective = "Reist nach Teldrassil und sucht Malfurions Agenten irgendwo außerhalb der Stadtmauern von Darnassus auf.", completion = "Die Geistergestalt schweigt, man hört lediglich ein leises Summen. Seltsam, aber sie scheint mit Euch über die Gedanken kommunizieren zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8734] = { id = 8734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrande und Remulos", description = "Tyrande wird benachrichtigt, Sterblicher. Shan'do Sturmgrimm hat mich für diesen Fall vorbereitet.\n\nIhr müsst jetzt zur Mondlichtung reisen und mit Remulos sprechen. Er wird weitere Anweisungen bezüglich der Herbeirufung von Eranikus haben.\n\nWir alle wünschen Euch viel Glück.", sourceObjective = "Reist zur Mondlichtung und sprecht mit Bewahrer Remulos.", completion = "Es würde unmöglich sein Eranikus aus dem Traum herbeizurufen, wenn er sich weigern sollte. Allerdings erfordern es seine Absichten, dass er unsere Welt betritt. Er will die lebende Manifestation von Malfurion zerstören. Der Erfolg dessen, würde das Ende für einen der mächtigsten Verbündeten des Traums bedeuten. Der Alptraum würde alles Verbleibende ganz und gar zerstören, sollte Malfurion fallen...", sourceObjectiveStatus = "unverified-source-field" }
quests[8735] = { id = 8735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis des Alptraums", description = "Ihr müsst zu den vier Traumportalen von Azeroth reisen und Euch jeweils ein Verderbnisfragment des Alptraums beschaffen. Die Drachkin, die in dieser Gegend hausen, werden derartige Fragmente bei sich tragen. Kommt zu mir zurück, sobald Ihr diese Fragmente eingesammelt habt.", sourceObjective = "Reist zu den vier Portalen des smaragdgrünen Traums in Azeroth und sammelt dort jeweils ein Verderbnisfragment des Alptraums ein. Kehrt zu Bewahrer Remulos bei der Mondlichtung zurück, sobald Ihr diese Aufgabe erfüllt habt.", progress = "<Remulos ist tief in Gedanken verloren.>", completion = "Seid Ihr vorbereitet? Ist die Welt auf das vorbereitet, was wir heraufbeschwören werden? Ich weiß es nicht... ich bin Malfurion zum Dienst verpflichtet. Dienst und Ehre...", sourceObjectiveStatus = "unverified-source-field" }
quests[8736] = { id = 8736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraum offenbart sich", description = "Wir müssen gegen Eranikus mit Bedacht vorgehen. Wir sollen ihn erlösen und nicht zerstören.\n\nTyrande ist bereits auf dem Weg, um uns bei dieser Aufgabe zu unterstützen. Wir müssen die Attacken des Drachen überstehen und Nachthafen vor der sicheren Zerstörung bewahren.\n\nSeid auf der Hut! Ihr und Eure Verbündeten seid unsere einzige Hoffnung.", sourceObjective = "Verteidigt Nachthafen gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande.", completion = "Er ist erlöst, {name}. Jetzt kehrt er in den Traum zurück, um zu richten, was er alleine zerstört hat. Eranikus wird ein mächtiger Verbündeter Malfurions und meines Vaters sein.\n\nDiese Rüstungsteile sind für Euch, {name}; Ysera selbst hat sie mir gegeben. Ihr würdet gut daran tun, wenn Ihr sie bei Euren Kämpfen gegen die Qiraji einsetzen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8737] = { id = 8737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurblauer Templer", description = "Die Anhänger des Schattenhammerklans und die von ihnen verehrten Elementarfürsten, stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj, können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen azurblauen Templer zu beschwören und zu vernichten. Meldet Euch dann bei Bor Wildmähne.", sourceObjective = "Beschwört und vernichtet einen azurblauen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz I, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr Eure Aufgabe bereits erfüllt, {name}?", completion = "Ausgezeichnete Arbeit, {name}. Hier ist Euer nächster Auftrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[8738] = { id = 8738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht des Regalschwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet, um Informationen zu sammeln. Späher Landion hat die Aktivitäten der Silithiden im Regalschwarm nun schon seit Tagen beobachtet. Findet ihn und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, {name}.", sourceObjective = "Setzt Euch mit dem cenarischen Späher Landion innerhalb des Regalschwarmbaus in Verbindung und bringt den Späherbericht des Regalschwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VII, um diese Aufgabe abschließen zu können.", progress = "Ihr findet Späher Landion innerhalb des Regalschwarmbaus. Beeilt Euch, {name}! Die Zeit spielt eine entscheidende Rolle.", completion = "Eure Bemühungen werden sehr geschätzt, {name}. Ich werde diese Beobachtungen sofort durchsehen, kümmert Euch ruhig schon um Eure nächste Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[8739] = { id = 8739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht des Ashischwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet. Späherin Jalia hat die Aktivitäten der Silithiden im Ashischwarm nun schon seit Tagen beobachtet. Findet sie und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, {name}.", sourceObjective = "Setzt Euch mit der cenarischen Späherin Jalia innerhalb des Ashischwarmbaus in Verbindung und bringt den Späherbericht des Ashischwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VIII, um diese Aufgabe abschließen zu können.", progress = "Ihr findet Späherin Jalia innerhalb des Ashischwarmbaus. Beeilt Euch, {name}! Die Zeit spielt eine entscheidende Rolle.", completion = "Eure Bemühungen werden sehr geschätzt, {name}. Ich werde diese Beobachtungen sofort durchsehen, kümmert Euch ruhig schon um Eure nächste Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[8740] = { id = 8740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodeure des Schattenhammers", description = "Es wurden mehrfach berittene Gruppen des Schattenhammerklans gesichtet, die außerhalb der Reichweite unserer Truppen in Burg Cenarius, kleinere Patrouillen und Karawanen angreifen.\n\nFindet und vernichtet die Marodeure des Schattenhammers, gemeinsam mit ihrem Anführer, einem furchterregenden Krieger namens Morna. Meldet Euch anschließend bei Windruferin Prachthorn.", sourceObjective = "Tötet Zwielichtmarodeurin Morna und 2 Zwielichtmarodeure. Erstattet anschließend Bericht bei Windruferin Prachthorn. Ihr benötigt auch den taktischen Einsatz IX, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr Eure Aufgabe bereits erfüllt, {name}?", completion = "Gut gemacht, {name}. Die Marodeure der Twilight haben unseren Patroullien ganz schöne Verluste beschert. Hier ist Euer nächster Auftrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[8741] = { id = 8741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held kehrt zurück", description = "Der Bewahrer erwartet Eure Rückkehr, {name}. Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit.", sourceObjective = "Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris.", progress = "<Anachronos nickt.>", completion = "Jeder wird von Euren Taten erfahren, Held. Man wird Loblieder von Orgrimmar bis weit in den südlichen Meeren singen. Jeder wird den Held des Bronzeschwarms kennen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8742] = { id = 8742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht von Kalimdor", sourceObjective = "Eintausend Jahre sind vergangen und wie es vorausgesagt wurde, steht die Eine nun vor mir. die Auserwählte, welche Ihr Volk in ein neues Zeitalter führen wird. Spürt Ihr es? Der alte Gott erzittert, {name}! Oh ja, er fürchtet Eure Bestimmung. Zerschlagt die Prophezeiung von C'thun!\n\nEr weiß, dass Ihr zu ihm kommen werdet - und mit Euch kommt die Macht von Kalimdor. Lasst es mich wissen, wenn Ihr bereit seid und ich werde Euch das Szepter der Sandstürme anvertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8743] = { id = 8743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt den Gong!", progress = "Die Oberfläche des Skarabäusgongs spiegelt bedrohlich das Licht der sengenden Sonne Silithus' wieder. Stählt Euch für das Kommende, denn wurde der Gong erst einmal geschlagen, werden sich die Tore nach Ahn'Qiraj öffnen. Dann wird es kein Zurück mehr geben\n\nIm züngelnden Antlitz der Bestie lauert nur Chaos und Zerstörung. Verteidigt Euer Volk!", completion = "Aus dem Erdreich vor dem Gong gräbt sich ein besonderer Kristall an die Oberfläche empor. Möglicherweise ein Geschenk der Brut." }
quests[8744] = { id = 8744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sorgfältig verpacktes Geschenk", sourceObjective = "Auf dem Kärtchen and diesem Geschenk steht:\n\nAn {name},\n\nmöge Euer Winterfest fröhlich und heiter verlaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8745] = { id = 8745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz des Zeitlosen", sourceObjective = "Seig gegrüßt, großer Held! Ich bin Jonathan, der Bewahrer des heiligen Gongs und ewige Wächter des bronzenen Drachenschwarms.\n\nDer Zeitlose hat mich dazu ermächtigt, Euch aus seinem Schatz einen Gegenstand Eurer Wahl zu gewähren. Möge er Euren Kampf gegen C'Thun erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[8746] = { id = 8746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen das Rentier", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir glauben, dass dieser schreckliche, monströse Griesgram, der sich im Vorgebirge des Hügellandes versteckt, ihn entführt hat. Gerade jetzt zur Festzeit können wir hier nicht weg. Bitte findet Metzen, besiegt seine Entführer und bringt ihn zu uns zurück!", sourceObjective = "Befreit Metzen das Rentier aus den Klauen seiner Entführer nahe der Eisfellhöhle im Vorgebirge des Hügellandes.", progress = "{name}! Habt Ihr ihn gefunden? Konntet Ihr den Notizen, die ich Euch mitgegeben habe, genug Informationen entnehmen, um ihn ausfindig zu machen? Mir wird ganz schlecht wenn ich daran denke, was diese fiesen Strolche ihm antun könnten… Ein so hohes Lösegeld können wir uns einfach nicht leisten.", completion = "Ihr habt es geschafft! Hurra!\n\nMetzen ist gerade eben erst zurück zu den Ställen von Altvater Winter geflogen. Ja, Metzen kann wirklich fliegen! Der Staub hat ganze Arbeit geleistet, ich wusste, das würde funktionieren. Ihr habt das Winterhauchfest und Kokelwälder vor dem Untergang bewahrt. Danke, {name}.\n\nHört mal, weil Ihr das für uns getan habt, möchte ich Euch das hier geben. Das ist etwas GANZ Besonderes. Wenn Ihr ein Reittier habt, werdet Ihr bestimmt eine Menge Spaß damit haben. Frohes Winterhauchfest!", sourceObjectiveStatus = "unverified-source-field" }
quests[8747] = { id = 8747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", sourceObjective = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Beschützers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden. Seine Macht wird Eure Verteidigungskraft um ein Vielfaches verstärken.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[8748] = { id = 8748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", progress = "Eure selbstlosen Bemühungen, die Kinder Kalimdors zu verteidigen, wurden zur Kenntnis genommen. Übergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Beschützers abkommen!" }
quests[8749] = { id = 8749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", progress = "Ihr ehrt meinesgleichen, {name}! Vernichtet die Feinde Kalimdors! Zeigt ihnen, was es heißt, das Land des ewigen Sternenlichts anzugreifen.\n\nIhr habt Euch eine weitere Verstärkung des Rings verdient. Übergebt mir Euren Siegelring, damit ich seine Kräfte erweitern kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Beschützers abkommen!" }
quests[8750] = { id = 8750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", progress = "Eine derartige Hingabe für eine gerechte Sache ist selten. Ihr habt die Unbeugsamkeit Eures Willens bewiesen, {name}! Dafür, dass Euer wacher Geist und Euer scharfer Verstand über diese Welt wacht, sollt Ihr reichhaltig belohnt werden.\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Beschützers abkommen!" }
quests[8751] = { id = 8751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beschützer von Kalimdor", progress = "Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Erhebt Euch, Beschützer von Kalimdor! Zeigt Euch und lasst Euch huldigen!" }
quests[8752] = { id = 8752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers", sourceObjective = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Eroberers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden. Seine Macht wird Eure physischen Angriffe um ein Vielfaches verstärken.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[8753] = { id = 8753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers", progress = "Eure selbstlosen Bemühungen, die Kinder Kalimdors zu verteidigen, wurden zur Kenntnis genommen. Übergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Eroberers abkommen!" }
quests[8754] = { id = 8754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers", progress = "Ihr ehrt meinesgleichen, {name}! Vernichtet die Feinde Kalimdors! Zeigt ihnen, was es heißt, das Land des ewigen Sternenlichts anzugreifen.\n\nIhr habt Euch eine weitere Verstärkung des Rings verdient. Übergebt mir Euren Siegelring, damit ich seine Kräfte erweitern kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Eroberers abkommen!" }
quests[8755] = { id = 8755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers", progress = "Eine derartige Hingabe für eine gerechte Sache ist selten. Ihr habt die Umbeugsamkeit Eures Willens bewiesen, {name}! Dafür, dass Euer wacher Geist und Euer scharfer Verstand über diese Welt wacht, sollt Ihr reichhaltig belohnt werden.\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Eroberers abkommen!" }
quests[8756] = { id = 8756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eroberer der Qiraji", progress = "Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Erhebt Euch, Eroberer der Qiraji! Zeigt Euch und lasst Euch huldigen!" }
quests[8757] = { id = 8757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Herbeirufers", sourceObjective = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Herbeirufers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden. Seine Macht wird Eure magischen und natürlichen Fähigkeiten um ein Vielfaches verstärken.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[8758] = { id = 8758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Herbeirufers", progress = "Eure selbstlosen Bemühungen, die Kinder Kalimdors zu verteidigen, wurden zur Kenntnis genommen. Übergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Herbeirufers abkommen!" }
quests[8759] = { id = 8759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Herbeirufers", progress = "Ihr ehrt meinesgleichen, {name}! Vernichtet die Feinde Kalimdors! Zeigt ihnen, was es heißt, das Land des ewigen Sternenlichts anzugreifen.\n\nIhr habt Euch eine weitere Verstärkung des Rings verdient. Übergebt mir Euren Siegelring, damit ich seine Kräfte erweitern kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Herbeirufers abkommen!" }
quests[8760] = { id = 8760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Herbeirufers", progress = "Eine derartige Hingabe für eine gerechte Sache ist selten. Ihr habt die Umbeugsamkeit Eures Willens bewiesen, {name}! Dafür, dass Euer wacher Geist und Euer scharfer Verstand über diese Welt wacht, sollt Ihr reichhaltig belohnt werden.\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Herbeirufers abkommen!" }
quests[8761] = { id = 8761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Herbeirufer", progress = "Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Erhebt Euch, großer Herbeirufer! Zeigt Euch und lasst Euch huldigen!" }
quests[8762] = { id = 8762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen das Rentier", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir glauben, dass dieser schreckliche, monströse Griesgram, der sich im Vorgebirge des Hügellandes versteckt, ihn entführt hat. Gerade jetzt zur Festzeit können wir hier nicht weg. Bitte findet Metzen, besiegt seine Entführer und bringt ihn zu uns zurück!", sourceObjective = "Befreit Metzen das Rentier aus den Klauen seiner Entführer nahe der Eisfellhöhle im Vorgebirge des Hügellandes.", progress = "{name}! Habt Ihr ihn gefunden? Konntet Ihr den Notizen, die ich Euch mitgegeben habe, genug Informationen entnehmen, um ihn ausfindig zu machen? Mir wird ganz schlecht wenn ich daran denke, was diese fiesen Strolche ihm antun könnten… Ein so hohes Lösegeld können wir uns einfach nicht leisten.", completion = "Ihr habt es geschafft! Hurra!\n\nMetzen ist gerade eben erst zurück zu den Ställen von Altvater Winter geflogen. Ja, Metzen kann wirklich fliegen! Der Staub hat ganze Arbeit geleistet, ich wusste, das würde funktionieren. Ihr habt das Winterhauchfest und Kokelwälder vor dem Untergang bewahrt. Danke, {name}.\n\nHört mal, weil Ihr das für uns getan habt, möchte ich Euch das hier geben. Das ist etwas GANZ Besonderes. Wenn Ihr ein Reittier habt, werdet Ihr bestimmt eine Menge Spaß damit haben. Frohes Winterhauchfest!", sourceObjectiveStatus = "unverified-source-field" }
quests[8763] = { id = 8763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held des Tages", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja der Held des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert - die bleiben dann für immer frisch! Wir benutzen sie um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr ein Meisterkoch seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.", sourceObjective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", progress = "Der Tannenzweigkonservierer sieht auf den ersten Blick wie eine Art Destillierapparat aus, bei genauerer Betrachtung werden allerdings einige goblinartige Veränderungen offensichtlich. Eure Fähigkeiten in der Kochkunst erlauben es Euch allerdings zu verstehen, wie die Maschine funktioniert.\n\nEs sind schon frische Tannenzweige in der Maschine - Ihr müsst nur noch Tiefsteinsalz dazugeben und fünf Goldstücke einwerfen, um sie ans Laufen zu bringen.", completion = "Die Maschine fängt an zu rumpeln und Dampf auszuspeien, während sie mit der Arbeit beginnt. Schon kurz darauf ist sie fertig. Sie spuckt noch etwas Dampf aus und eine Klappe öffnet sich. In der Öffnung befindet sich ein Bündel konservierter Tannenzweige.", sourceObjectiveStatus = "unverified-source-field" }
quests[8764] = { id = 8764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad wechseln - Kein Beschützer mehr" }
quests[8765] = { id = 8765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad wechseln - Kein Herbeirufer mehr" }
quests[8766] = { id = 8766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad wechseln - Kein Eroberer mehr" }
quests[8767] = { id = 8767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:B\nFür {name}, einen ganz besonderen Helden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8768] = { id = 8768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fröhlich verpacktes Geschenk", sourceObjective = "Auf diesem festlich verpackten Geschenk steht Euer Name!\n\n Hat sich das etwa gerade bewegt?", sourceObjectiveStatus = "unverified-source-field" }
quests[8769] = { id = 8769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tickendes Geschenk", sourceObjective = "Ein wundervolles Winterhauchfest wünschen Euch Eure Freunde bei Kokelwälder.", sourceObjectiveStatus = "unverified-source-field" }
quests[8770] = { id = 8770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Verteidiger des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Verteidiger des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Verteidiger des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz I, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Euer Eifer ist bemerkenswert!", sourceObjectiveStatus = "unverified-source-field" }
quests[8771] = { id = 8771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Sandpirscher des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Sandpirscher des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Sandpirscher des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz II, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Ashischwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8772] = { id = 8772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Wegbehüter des Zoraschwarms", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Wegbehüter des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Wegbehüter des Zoraschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VI, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Zoraschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8773] = { id = 8773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Häscher des Zoraschwarms", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Häscher des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Häscher des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IV, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Ich habe nur Gutes über Eure Teilnahme an dem Angriff gegen den Zoraschwarm gehört. Macht so weiter und der Sieg wird schon bald unser sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8774] = { id = 8774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Wegelagerer des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt, je weiter die Kriegsvorbereitungen voranschreiten, eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Wegelagerer des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Wegelagerer des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VIII, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8775] = { id = 8775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Feuerspucker des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Feuerspucker des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Feuerspucker des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IX, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8776] = { id = 8776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Sklavenjäger des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt, je weiter die Kriegsvorbereitungen voranschreiten, eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Sklavenjäger des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Sklavenjäger des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz X, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8777] = { id = 8777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Einbuddler des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Einbuddler des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Einbuddler des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XI, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8778] = { id = 8778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eisenschmiedebrigade braucht Sprengstoff!", description = "Uns liegt eine Anforderung der Eisenschmiedebrigade vor, die eine Menge... na sagen wir, recht explosive Komponenten umfasst. Beschafft diese Komponenten und bringt sie zu einem Kerl namens Sprinkelstaub, einem Mitglied der Eisenschmiedebrigade.", sourceObjective = "Bringt Arkanist Sprinkelstaub nahe des Zoraschwarmbaus in Silithus 6 Öle des Feuerbrandes, 5 Einheiten Goblinraketentreibstoff und 10 Einheiten dichtes Sprengpulver. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr die Materialien, {name}?", completion = "Ah, sehr gut. Das kommt mir alles sehr gelegen! Ich muss Euch danken, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8779] = { id = 8779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Materialien", description = "Geologin Lerchenbanns Studien haben sich für unsere Operationen in Silithus als sehr wertvoll erwiesen. Vor Kurzem hat sie eine Ladung magischer Materialien angefordert, die sie für ihre weiteren Forschungen dringend benötigt.\n\nBeschafft die notwendigen Materialien und liefert sie direkt an sie aus, damit Geologin Lerchenbann ihre Forschungen ungestört fortsetzen kann.", sourceObjective = "Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und einen gewaltigen Smaragd zu Geologin Lerchenbann auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, diese hier sind mir von großem Nutzen! Wisst Ihr {name}, in dieser Wüste ist es sehr schwer an derartige Materialien zu kommen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[8780] = { id = 8780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungssets für den Feldeinsatz", description = "Der Eisenschmiedebrigade gehen im Feld die Rüstungssets aus. Schnappt Euch eine Ladung und bringt sie zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau.", sourceObjective = "Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau in Silithus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Vielen Dank, ich werde alles direkt an unsere Truppen ausgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8781] = { id = 8781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für den Feldeinsatz", description = "Die Eisenschmiedebrigade hat sich in den Kämpfen von Silithus als ein würdiger Verbündeter erwiesen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Vorräte eingebüßt. Beschafft eine Ladung Waffen und bringt sie zu Janela Starkhammer nahe des Baus des Zoraschwarms.", sourceObjective = "Bringt 2 Mondstahlbreitschwerter zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Oh, fantastisch! Endlich muss ich mir kein Gemaule über stumpfe Waffen mehr anhören. Vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8782] = { id = 8782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniformnachschub", description = "Die letzte Ladung neuer Rekruten hat uns einen Engpass an Uniformen beschert. Beschafft uns eine Ladung Schneiderwaren, damit wir mehr Uniformen herstellen können. Bringt alles zur Windruferin Prachthorn.", sourceObjective = "Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, genau was wir jetzt brauchen. Wir wissen Eure Arbeit sehr zu schätzen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8783] = { id = 8783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Materialien", description = "Vargus, der Schmied von Burg Cenarius, hat verzauberte Materialien zur Herstellung von stärkeren Waffen angefordert. Beschafft die benötigten Materialien und bringt sie direkt zu Vargus, um den hohen Ausrüstungsstand unserer Truppen auf Burg Cenarius aufrechtzuerhalten.", sourceObjective = "Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, sehr gut. Dieses Material ist von hervorragender Qualität. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8784] = { id = 8784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Qiraji", description = "Ihr habt ein uraltes Artefakt der Qiraji entdeckt! Vielleicht interessiert sich einer der Drachen am Eingang des Tempels für dieses Relikt.", sourceObjective = "Bringt das uralte Qirajiartefakt zu den Drachen, die sich nahe des Tempeleingangs versteckt halten.", progress = "Ihr glüht! Ich weiß, was das bedeutet…", completion = "Ein einmaliger Fund, {name}. Einfach fantastisch! Mit Hilfe dieses Artefakts, erhalten wir sicherlich einen Einblick in die verquerte Denkensweise des Feindes.", sourceObjectiveStatus = "unverified-source-field" }
quests[8785] = { id = 8785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Orgrimmarlegion braucht Mojo!", description = "Uns liegt eine Anforderung der Orgrimmarlegion vor, die eine Menge recht ungewöhnliche Materialien umfasst. Aber in Anbetracht ihrer jüngsten Leistungen in Silithus, möchten wir dieser Anfrage so schnell wie möglich nachkommen. Beschafft die notwendigen Materialien und bringt sie einer Trollfrau namens Shai.", sourceObjective = "Bringt Schattenpriesterin Shai nahe des Regalschwarmbaus in Silithus 6 Einheiten mächtiges Mojo, 6 Fläschchen großes Mojo und 8 Öle des Feuerbrandes. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr die Materialien, {name}?", completion = "Ah, sehr gut. Genau, was ich gebraucht habe. Aus diesen Zutaten werde ich ein ganz spezielles Gebräu mischen. Den Silithiden wird es bestimmt nicht gut bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8786] = { id = 8786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für den Feldeinsatz", description = "Die Orgrimmarlegion hatte bereits vor einiger Zeit zusätzliche Waffen angefordert, die wir bisher noch nicht liefern konnten. Beschafft die notwendigen Waffen und bringt sie zu Merok Langschreiter außerhalb des Regalschwarmbaus.", sourceObjective = "Bring 3 massive Eisenäxte zu Merok Langschreiter im Lager der Orgrimmarlegion außerhalb des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ausgezeichnete Arbeit. Unsere Vorräte gingen gerade zur Neige, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8787] = { id = 8787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungssets für den Feldeinsatz", description = "Die Orgrimmarlegion ist zu unserer Unterstützung in Silithus eingetroffen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Rüsstungssets eingebüßt. Beschafft eine Ladung und bringt sie zu Merok Langschreiter im Lager der Orgrimmarlegion.", sourceObjective = "Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Merok Langschreiter nahe des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, ja… Ich werde alles direkt an die Truppe ausgeben, {name}. Die Orgrimmarlegion ist Euch zu Dank verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8788] = { id = 8788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, einen ganz besonderen Helden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8789] = { id = 8789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Qirajiwaffen", description = "Wir haben hier nicht ein Jahrtausend in völliger Untätigkeit verbracht, {name}. Wir sahen mit eigenen Augen, wie sich diese Biester an ihren eigenen Artgenossen gütlich taten, nachdem diese ihre Nützlichkeit für den Schwarm verloren hatten. Wir lauschten, als sie ihre Pläne schmiedeten, diese Welt in Schutt und Asche zu legen. Und wir lernten, wie sich Verrat und Missgunst in ihren Reihen ausbreiten.\n\nSie haben Schwächen und wir wissen nun, wie wir diese zu unserem Vorteil nutzen können.\n\nFindet und bringt mir ihre Zeremonienwaffen. Zusammen, mit dem durch ihren Gott erschaffenen Element, werden wir daraus mächtige Instrumente der Zerstörung erschaffen.", sourceObjective = "Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Elementiumblöcke bringt.", progress = "Findet, worum ich Euch gebeten habe und Ihr werdet weit mehr als nur die Summe Eurer Teile werden, großer Held.", completion = "Jetzt, da diese Waffen mit Elementium erfüllt sind, werden sie sich mit Leichtigkeit durch jeden Qiraji und ihren Gott schneiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8790] = { id = 8790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Qirajiinsignien", description = "Arygos hat die Theorie aufgestellt, dass das Element, welches während des Konflikts zwischen den uralten Göttern und ihren Anhängern entstanden ist, unter den richtigen Bedingungen für sie tödlich ist. Ich spreche vom Elementium, <Sterblicher/Sterbliche>.\n\nFindet und bringt mir imperiale Qirajiinsignien sowie das giftige Element, dann werde ich Euch Waffen von größter Macht erschaffen!", sourceObjective = "Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Elementiumblöcke.", progress = "Ihr werdet sie niederstrecken und uns von diesen Fesseln befreien.", completion = "Nutzt diesen Gegenstand weise, {name}. Lasst sie den Schmerz ihrer Opfer am eigenen Leib erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[8791] = { id = 8791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang von Ossirian", description = "Eine schreckliche Bedrohung hat ihr Ende gefunden. Der grausame Ossirian existiert nicht mehr.\n\nDie Bewohner Kalimdors werden aufatmen, wenn sie von diesem glorreichen Sieg erfahren. Nehmt Ossirians Kopf und bringt ihn zu Kommandant Mar'alith auf Burg Cenarius.", sourceObjective = "Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus.", progress = "Ah, {name}. Wie ich sehe, seid Ihr zurückgekehrt und sogar in einem Stück! Welche Neuigkeiten bringt Ihr aus Ahn'Qiraj?", completion = "Ich entbiete Euch meine höchste Anerkennung und erlaube es Euch, einen Gegenstand von höchster Macht auszuwählen, {name}! Ihr habt den Bewohnern von Kalimdor einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8792] = { id = 8792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Euch!", description = "Hallo, schön, dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", completion = "Throm'ka, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8793] = { id = 8793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Euch!", description = "Hallo, schön, dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", completion = "Throm'ka, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
