quests[8795] = { id = 8795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Euch!", description = "Hallo, schön, dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Schneefall. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede.", completion = "Seid gegrüßt, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Allianz haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
