quests[8797] = { id = 8797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Euch!", description = "Hallo, schön, dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Schneefall. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede.", completion = "Seid gegrüßt, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Allianz haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8798] = { id = 8798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer eigener Yeti", sourceObjective = "Hey! Wisst Ihr was?! Ihr seid auch Ingenieur! So, da Ihr mir dabei geholfen habt meinen Freunden eine Lektion zu erteilen, werde ich Euch jetzt lehren, wie Ihr Euren eigenen mechanischen Yeti herstellt! Jetzt kann der Spaß für immer weitergehen und Ihr könnt wem immer Ihr wollt einen Schrecken einjagen! Vorausgesetzt Ihr treibt die benötigten Teile dafür auf.\n\nNa, was sagt Ihr, {name}? Wollt Ihr, dass ich Euch in das Geheimnis der Herstellung eines mechanischen Yetis einweihe?", sourceObjectiveStatus = "unverified-source-field" }
quests[8799] = { id = 8799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held des Tages", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja der Held des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert - die bleiben dann für immer frisch! Wir benutzen sie um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr ein Meisterkoch seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.", sourceObjective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", progress = "Der Tannenzweigkonservierer sieht auf den ersten Blick wie eine Art Destillierapparat aus, bei genauerer Betrachtung werden allerdings einige goblinartige Veränderungen offensichtlich. Eure Fähigkeiten in der Kochkunst erlauben es Euch allerdings zu verstehen, wie die Maschine funktioniert.\n\nEs sind schon frische Tannenzweige in der Maschine - Ihr müsst nur noch Tiefsteinsalz dazugeben und fünf Goldstücke einwerfen, um sie ans Laufen zu bringen.", completion = "Die Maschine fängt an zu rumpeln und Dampf auszuspeien, während sie mit der Arbeit beginnt. Schon kurz darauf ist sie fertig. Sie spuckt noch etwas Dampf aus und eine Klappe öffnet sich. In der Öffnung befindet sich ein Bündel konservierter Tannenzweige.", sourceObjectiveStatus = "unverified-source-field" }
quests[8800] = { id = 8800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Cenarius", description = "Zwischen dem Erledigen der Euch im Krieg zugeteilten Aufträge, solltet Ihr ab und an mit Vargus dem Schmied sprechen. Zeigt ihm Eure erworbenen Abzeichen und er wird Euch im Gegenzug mit der Eurem Einsatz entsprechenden Ausrüstung versorgen.", sourceObjective = "Sprecht mit Vargus auf Burg Cenarius in Silithus.", completion = "Kaldon schickt Euch? Nun gut, lasst uns sehen, was ich für Euch tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[8801] = { id = 8801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "C'Thuns Vermächtnis", description = "Die Mauern von Ahn'Qiraji erbeben. Eine finstere Macht, älter noch als die Welt, wurde vernichtet.\n\nAls Ihr auf die Überreste der gigantischen Scheußlichkeit hinab blickt, scheint Euer Herz fast zu gefrieren. Selbst im Tod, könnt Ihr das böse Erbe C'Thuns um Euch herum spüren.\n\nIhr habt das Unmögliche vollbracht.\n\nEines seiner Augen, scheint Euch noch immer anzustarren. Ihr nehmt es auf und verstaut es in Eurem Gepäck.\n\nBringt den Drachen im nächsten Raum das Auge von C'Thun.", sourceObjective = "Bringt Caelastrasz im Tempel von Ahn'Qiraj das Auge von C'Thun.", progress = "<Caelastrasz kniet vor Euch.>\n\nLord {name}, Ihr habt uns aus seinem Griff befreit.", completion = "Lord {name}, wir werden diesen Ort aus eigener Kraft verlassen, sobald wir sicher sind, dass alles Böse in diesen Mauern vernichtet wurde. Eure sagenumwobene Reise nähert sich ihrem Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[8802] = { id = 8802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Retter von Kalimdor", description = "Begebt Euch zu den Höhlen der Zeit, <Lord/Lady> {name}. Anachronos erwartet Eure Rückkehr. Übergebt ihm das Auge von C'Thun. Sicherlich wird er es der Sammlung seines Meisters hinzufügen wollen.", sourceObjective = "Bringt Anachronos in den Höhlen der Zeit das Auge von C'Thun.", progress = "Lord {name}! Es ist vollbracht...", completion = "Der Meister hat dies für Euch zurückgelassen, großer Held. Aus dem zeitlosen Schatz: Eine Sammlung veschiedenster Artefakte, über tausende von Jahren zusammengetragen. Ihr habt die Wahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[8803] = { id = 8803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Festtagsgeschenk", sourceObjective = "Auf dem Schildchen des Geschenks steht:\n\nFür {name},\n\nIch hoffe, dieses Geschenk wird Euch dabei helfen, einen Hauch von Gemütlichkeit und Festtagsfreude in ganz Azeroth zu verbreiten.\n\nAltvater Winter", sourceObjectiveStatus = "unverified-source-field" }
quests[8804] = { id = 8804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenüberlebenspaket", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", sourceObjective = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Diese Pakete haben wir wirklich dringend benötigt, {name}. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8805] = { id = 8805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stiefel für die Wache", description = "Die berittene Einheit der Wache von Burg Cenarius hat kaum noch Vorräte an verschnörkelten Mithrilstiefeln. Beschafft Euch eine Ladung und bringt sie sofort zu Hauptmann Vish Kozus auf Burg Cenarius.", sourceObjective = "Bringt 3 Paar verschnörkelte Mithrilstiefel zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz II, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Wir hatten diese Stiefel wirklich dringend benötigt, {name}. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8806] = { id = 8806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleifsteine für die Wache", description = "Die Wache von Burg Cenarius hat kaum noch Vorräte an Schleifsteinen. Beschafft Euch eine Ladung und bringt sie sofort zu Hauptmann Vish Kozus auf Burg Cenarius.", sourceObjective = "Bringt 10 verdichtete Schleifsteine, 10 robuste Schleifsteine und 10 schwere Schleifsteine zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz III, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Wir hatten diese Schleifsteine wirklich dringend benötigt, {name}. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8807] = { id = 8807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Materialien", description = "Geologin Lerchenbanns Studien haben sich für unsere Operationen in Silithus als sehr wertvoll erwiesen. Vor Kurzem hat sie eine Ladung magischer Materialien angefordert, die sie für ihre weiteren Forschungen dringend benötigt.\n\nBeschafft die notwendigen Materialien und liefert sie direkt an sie aus, damit Geologin Lerchenbann ihre Forschungen ungestört fortsetzen kann.", sourceObjective = "Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und 1 gewaltigen Smaragd zu Geologin Lerchenbann auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, diese hier sind mir von großem Nutzen! Wisst Ihr {name}, in dieser Wüste ist es sehr schwer an derartige Materialien zu kommen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[8808] = { id = 8808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniformnachschub", description = "Die letzte Ladung neuer Rekruten hat uns einen Engpass an Uniformen beschert. Beschafft uns eine Ladung Schneiderwaren, damit wir mehr Uniformen herstellen können. Bringt alles zur Windruferin Prachthorn.", sourceObjective = "Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, genau was wir jetzt brauchen. Wir wissen Eure Arbeit sehr zu schätzen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8809] = { id = 8809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Materialien", description = "Vargus, der Schmied von Burg Cenarius, hat verzauberte Materialien zur Herstellung von stärkeren Waffen angefordert. Beschafft die benötigten Materialien und bringt sie direkt zu Vargus, um den hohen Ausrüstungsstand unserer Truppen auf Burg Cenarius aufrechtzuerhalten.", sourceObjective = "Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, sehr gut. Dieses Material ist von hervorragender Qualität. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8810] = { id = 8810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbände für den Feldeinsatz", description = "Nach den neusten Verlusten, die wir hinnehmen mussten, gehen unsere Vorräte an Verbänden für das Schlachtfeld gefährlich zur Neige. Besorgt Euch eine Ladung an Vorräten für Erste Hilfe und bringt sie zu Windruferin Prachthorn auf Burg Cenarius.", sourceObjective = "Bringt 30 schwere Runenstoffverbände, 30 schwere Seidenverbände und 30 schwere Magiestoffverbände zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz X, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Gerade rechtzeitig. Dieser Nachschub wird Leben retten, {name}. Man schätzt Eure Arbeit. Hier ist Eure nächste Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[8811] = { id = 8811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen", progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Darnassus ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Darnassus würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, {class}!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet." }
quests[8812] = { id = 8812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen", progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf bei den Gnomereganverbannten ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf bei den Gnomereganverbannten würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, {class}!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet." }
