quests[8835] = { id = 8835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Ironforge sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Ironforge nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, {name}, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen." }
quests[8836] = { id = 8836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen", progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Stormwind ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Stormwind würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, {class}!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet." }
