quests[8845] = { id = 8845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Darkspearstamm sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, {name}, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen." }
quests[8846] = { id = 8846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fünf Abzeichen gegen Kriegsmaterial tauschen", progress = "Ah, sicherlich seid Ihr gekommen, um zusätzliches Kriegsmaterial für Euch anzufordern. Nun, ich kann das sehr gut nachvollziehen, im Krieg mangelt es ständig an allem… Ihr braucht Euch bloß hier umzusehen, dann wißt Ihr was ich meine!\n\nIch bin bevollmächtigt zusätzliches Kriegsmaterial an Euch auszugeben, allerdings müsst Ihr mir dafür eine entsprechende Anzahl Belobigungsabzeichen überlassen. Durch diesen Tausch wird zwar Euer Ruf nicht weiter verbessert werden, doch möglicherweise findet Ihr etwas brauchbares für die Schlacht und rettet so vielleicht Euer Leben.", completion = "Nun, dann sind wir uns ja einig. Hier sind die von Euch angeforderten Kriegsmaterialien, {class}. Wenn Ihr wieder einmal etwas brauchen solltet, kommt direkt zu mir. Ich werde Eure Anforderung dann schnellstmöglich bearbeiten.\n\nLeistet weiter so gute Arbeit, {name}! Wir können jeden Mann und jede Frau gebrauchen, um diesen Krieg zu gewinnen. Wenn alle ihre Pflicht so gewissenhaft erfüllen, sollten wir aus dieser Schlacht als Sieger hervorgehen." }
quests[8847] = { id = 8847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Abzeichen gegen Kriegsmaterial tauschen" }
quests[8848] = { id = 8848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fünfzehn Abzeichen gegen Kriegsmaterial tauschen", progress = "Ah, sicherlich seid Ihr gekommen, um zusätzliches Kriegsmaterial für Euch anzufordern. Nun, ich kann das sehr gut nachvollziehen, im Krieg mangelt es ständig an allem… Ihr braucht Euch bloß hier umzusehen, dann wißt Ihr was ich meine!\n\nIch bin bevollmächtigt zusätzliches Kriegsmaterial an Euch auszugeben, allerdings müsst Ihr mir dafür eine entsprechende Anzahl Belobigungsabzeichen überlassen. Durch diesen Tausch wird zwar Euer Ruf nicht weiter verbessert werden, doch möglicherweise findet Ihr etwas brauchbares für die Schlacht und rettet so vielleicht Euer Leben.", completion = "Nun, dann sind wir uns ja einig. Hier sind die von Euch angeforderten Kriegsmaterialien, {class}. Wenn Ihr wieder einmal etwas brauchen solltet, kommt direkt zu mir. Ich werde Eure Anforderung dann schnellstmöglich bearbeiten.\n\nLeistet weiter so gute Arbeit, {name}! Wir können jeden Mann und jede Frau gebrauchen, um diesen Krieg zu gewinnen. Wenn alle ihre Pflicht so gewissenhaft erfüllen, sollten wir aus dieser Schlacht als Sieger hervorgehen." }
quests[8849] = { id = 8849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwanzig Abzeichen gegen Kriegsmaterial tauschen", progress = "Ah, sicherlich seid Ihr gekommen, um zusätzliches Kriegsmaterial für Euch anzufordern. Nun, ich kann das sehr gut nachvollziehen, im Krieg mangelt es ständig an allem… Ihr braucht Euch bloß hier umzusehen, dann wißt Ihr was ich meine!\n\nIch bin bevollmächtigt zusätzliches Kriegsmaterial an Euch auszugeben, allerdings müsst Ihr mir dafür eine entsprechende Anzahl Belobigungsabzeichen überlassen. Durch diesen Tausch wird zwar Euer Ruf nicht weiter verbessert werden, doch möglicherweise findet Ihr etwas brauchbares für die Schlacht und rettet so vielleicht Euer Leben.", completion = "Nun, dann sind wir uns ja einig. Hier sind die von Euch angeforderten Kriegsmaterialien, {class}. Wenn Ihr wieder einmal etwas brauchen solltet, kommt direkt zu mir. Ich werde Eure Anforderung dann schnellstmöglich bearbeiten.\n\nLeistet weiter so gute Arbeit, {name}! Wir können jeden Mann und jede Frau gebrauchen, um diesen Krieg zu gewinnen. Wenn alle ihre Pflicht so gewissenhaft erfüllen, sollten wir aus dieser Schlacht als Sieger hervorgehen." }
quests[8850] = { id = 8850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreißig Abzeichen gegen Kriegsmaterial tauschen", progress = "Ah, sicherlich seid Ihr gekommen, um zusätzliches Kriegsmaterial für Euch anzufordern. Nun, ich kann das sehr gut nachvollziehen, im Krieg mangelt es ständig an allem… Ihr braucht Euch bloß hier umzusehen, dann wißt Ihr was ich meine!\n\nIch bin bevollmächtigt zusätzliches Kriegsmaterial an Euch auszugeben, allerdings müsst Ihr mir dafür eine entsprechende Anzahl Belobigungsabzeichen überlassen. Durch diesen Tausch wird zwar Euer Ruf nicht weiter verbessert werden, doch möglicherweise findet Ihr etwas brauchbares für die Schlacht und rettet so vielleicht Euer Leben.", completion = "Nun, dann sind wir uns ja einig. Hier sind die von Euch angeforderten Kriegsmaterialien, {class}. Wenn Ihr wieder einmal etwas brauchen solltet, kommt direkt zu mir. Ich werde Eure Anforderung dann schnellstmöglich bearbeiten.\n\nLeistet weiter so gute Arbeit, {name}! Wir können jeden Mann und jede Frau gebrauchen, um diesen Krieg zu gewinnen. Wenn alle ihre Pflicht so gewissenhaft erfüllen, sollten wir aus dieser Schlacht als Sieger hervorgehen." }
