quests[8855] = { id = 8855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreißig Abzeichen gegen Kriegsmaterial tauschen", progress = "Ah, sicherlich seid Ihr gekommen, um zusätzliches Kriegsmaterial für Euch anzufordern. Nun, ich kann das sehr gut nachvollziehen, im Krieg mangelt es ständig an allem… Ihr braucht Euch bloß hier umzusehen, dann wißt Ihr was ich meine!\n\nIch bin bevollmächtigt zusätzliches Kriegsmaterial an Euch auszugeben, allerdings müsst Ihr mir dafür eine entsprechende Anzahl Belobigungsabzeichen überlassen. Durch diesen Tausch wird zwar Euer Ruf nicht weiter verbessert werden, doch möglicherweise findet Ihr etwas brauchbares für die Schlacht und rettet so vielleicht Euer Leben.", completion = "Nun, dann sind wir uns ja einig. Hier sind die von Euch angeforderten Kriegsmaterialien, {class}. Wenn Ihr wieder einmal etwas brauchen solltet, kommt direkt zu mir. Ich werde Eure Anforderung dann schnellstmöglich bearbeiten.\n\nLeistet weiter so gute Arbeit, {name}! Wir können jeden Mann und jede Frau gebrauchen, um diesen Krieg zu gewinnen. Wenn alle ihre Pflicht so gewissenhaft erfüllen, sollten wir aus dieser Schlacht als Sieger hervorgehen." }
quests[8856] = { id = 8856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenüberlebenspaket", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", sourceObjective = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 gebackene Lachse zu Calandrath in der Taverne von Burg Cenarius in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[8857] = { id = 8857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Ashi", description = "Ich suche nach schlachterprobten Abenteurern, die für mich eine Fragmentprobe vom Koloss des Ashischwarms zu Glotz in Beutebucht bringen. Nein, nein, Ihr braucht Euch nicht einmal in die Nähe dieses Giganten zu wagen. Nehmt einfach eine von meinen Proben und beeilt Euch. Verrottet nutzt sie Glotz nicht viel!", sourceObjective = "Bringt das Fragment vom Koloss des Ashischwarms zu Glotz Widrikus in Beutebucht.", progress = "Ja? Was habt Ihr für mich?", completion = "Oh, was für tolle Hühnchen ich aus diesem wundervollen Fragment basteln werde! Vielen Dank, mein Junge!", sourceObjectiveStatus = "unverified-source-field" }
quests[8858] = { id = 8858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Regal", description = "Ich würde nichts lieber tun, als Schlickfaust dieses verdammte Fragment in sein fettes Maul zu stopfen. Stattdessen stecke ich hier fest und sammle Proben von dieser zu groß geratenen Kakerlake! In Anbetracht ihrer Größe, werde ich hier wohl noch eine Weile beschäftigt sein.\n\nNehmt diese Probe und bringt sie für mich zu Schlickfaust... und beeilt Euch, {class}. Er zahlt auch sehr gut!\n\nAlso, ab zur Thoriumspitze in die sengende Schlucht.", sourceObjective = "Bringt das Fragment vom Koloss des Regalschwarms zu Aufseher Schlickfaust in die sengende Schlucht.", completion = "Hervorragend! Aus diesem Chitinfragment können wir sicherlich einige sehr mächtige Rüstungen herstellen. Hier ist Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[8859] = { id = 8859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Zora", description = "Meine Leute hätte es beinahe erwischt, als sie diese Probe beschafft haben. Ihr müsst Euch unbedingt beeilen! Lord Maxwell Tyrosus wartet bereits voller Ungeduld auf eine frische Fragmentprobe. Er geht davon aus, dass uns die Geheimnisse dieses Kolosses im Kampf gegen die Geißel sehr von Nutzen sein werden!\n\nWieso seid Ihr noch hier!? Zur Kapelle des Hoffnungsvollen Lichts! Ja, ja, man wird Euch für diese Aufgabe großzügig entlohnen...", sourceObjective = "Bringt das Fragment vom Koloss des Zoraschwarms zu Lord Maxwell Tyrosus an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", progress = "Ihr seht ein wenig schwerfällig aus, mein Freund.", completion = "Exzellent und genau zur rechten Zeit! Gut gemacht, Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[8860] = { id = 8860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neujahrsfeier!", description = "In Sturmwind wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlos was Hochprozentiges zu trinken und nachts eine fantastische Feuerwerksschau! Das wird sicherlich ein Riesenspaß... allerdings findet auch in Beutebucht eine Neujahrsfeier statt. Ich wette, dort ist noch viel mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Allison eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, {name}! Ihr findet Gastwirtin Allison in der Taverne zur güldenen Rose, drüben im Handelsdistrikt von Sturmwind.", sourceObjective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Allison in Sturmwind.", progress = "Hallo! Seid Ihr wegen der Party hier? Oder wollt Ihr nur ein wenig Eure müden Füße ausruhen?", completion = "Oh, meine Vorräte von Kokelwälder! Großartig! Die brauche ich dringend, um all die hungrigen Mäuler während der Feierlichkeiten zu stopfen!\n\nVielen Dank für Eure Hilfe, {name}. Bitte, nehmt dies als Belohnung an und vergesst nicht mit den anderen draußen zu trinken und zu tanzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8861] = { id = 8861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neujahrsfeier!", description = "In Donnerfels wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlos was Hochprozentiges zu trinken und nachts eine fantastische Feuerwerksschau! Das wird sicherlich ein Riesenspaß... allerdings findet auch in Beutebucht eine Neujahrsfeier statt. Ich wette, dort ist noch viel mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Pala eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, {name}! Ihr findet Gastwirtin Pala in der Taverne nahe der Brücke zur Anhöhe der Jäger.", sourceObjective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Pala in Donnerfels.", progress = "Guten Tag, {class}! Seid Ihr wegen den Feierlichkeiten nach Thunder Bluff gekommen? Oder wollt Ihr nur ein wenig Eure von der Jagd müden Hufe ausruhen?", completion = "Oh, sehr gut! Mit diesen Vorräten sollte ich alle Feiernden auf dem Neujahrsfest bewirten können!\n\nIch danke Euch, {name}. Ich stehe in Eurer Schuld. Bitte, nehmt diese Münzen als Dankeschön... und befolgt meinen Rat - nehmt einen herzhaften Schluck aus dem Fass draußen und schließt Euch den anderen beim Feiern des neuen Jahres an!", sourceObjectiveStatus = "unverified-source-field" }
quests[8862] = { id = 8862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Kerze", progress = "Elunes Kerze ist für die Anhänger des Mondfests ein Artefakt der großen Verehrung. Die Kerze beinhaltet wahres Mondlicht, bereit zur Freigabe!\n\nDieses Licht ist für die meisten Kreaturen harmlos, aber Ihr werdet sehen, dass Omen und seine Diener davon Verbrennungen erleiden und geblendet werden.", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt Elunes Kerze mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nMöge Euer Mondfest freudig und voller Heiterkeit sein, {name}.\n\nMöchtet Ihr Euch Omen und seinen Dienern wirklich stellen, so werdet Ihr Elunes Kerze recht nützlich finden..." }
quests[8863] = { id = 8863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagsklöße", progress = "Wenn Ihr hungrig seid, dann solltet ihr zu der richtigen Adresse kommen!\n\nKlöße sind das traditionelle Gericht des Mondfests; man serviert es bereits seit den Zeiten des ersten Mondfests und ich bin stolz, dass ich diese Köstlichkeit während der diesjährigen Feierlichkeiten anbieten kann. Im Austausch gegen eine einzige Münze der Urahnen werde ich Euch von einer Probe dieses unvergleichlich genüsslichen Gerichts kosten lassen!", completion = "Ausgezeichnet - bitte genießt diese Klöße mit meinen besten Wünschen. Auch wenn sie nur ein kleines Zeichen der Anerkennung für Eure Ehre sind, die Ihr Euch mittels Eurer Taten verdient habt, so denke ich doch, dass Ihr sie alle gleichermaßen genießen werdet.\n\nSolltet Ihr noch mehr Münzen der Urahnen besitzen, so bin ich gewillt Euch ein reiches Angebot an Gegenständen im Austausch dafür anzubieten." }
quests[8864] = { id = 8864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagskleider des Mondfests", progress = "Ich habe eine Auswahl an Kleidern, die Euch interessieren könnte. Derartige Gewänder wurden in vergangenen Zeiten während des Mondfests getragen. Die Auswahl, die ich heute zu bieten habe, ist vielleicht die beste, die ich jemals gesehen habe. Jedes Stück ist aus den feinsten und geschmeidigsten Materialien handgefertigt worden.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt dieses Kleid mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nDa Ihr unsere Urahnen geehrt habt, ehrt Ihr mich mit Eurer bloßen Anwesenheit. Ich danke Euch, möge Euer Mondfest freudig sein." }
quests[8865] = { id = 8865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festliche Hosenanzüge des Mondfests", progress = "Ich freue mich Euch mitteilen zu können, dass ich über eine feine Auswahl an festlichen Hosenanzügen verfüge, die ich Euch anbieten kann... aber nur im Tausch gegen Münzen der Urahnen. Wenn Ihr Wert auf Eure Erscheinung legt, dann ist dies genau das Richtige für Euch! Ich kann Euch versichern, dass Ihr keine vergleichbaren Hosenanzüge finden werdet.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt diesen Hosenanzug mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nSolltet Ihr noch mehr Münzen der Urahnen zum Tauschen haben, dann sprecht noch einmal mit mir. Ich habe während des gesamten Mondfests zahlreiche Gegenstände in meinem Angebot." }
quests[8866] = { id = 8866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Bronzebart", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8867] = { id = 8867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondfeuerwerk", description = "Die Druiden der Mondlichtung feiern jedes Jahr den großen Triumph unserer Stadt über ein uraltes Übel.\n\nWir ehren die Weisheit unserer Urahnen, nehmen an herrlichen Festgelagen teil und... schießen natürlich Feuerwerk ab!\n\nFür eine kleine Spende könnt Ihr bei unserem Verkäufer farbenfrohe Raketen erwerben. Versucht doch mal einen der hier herumstehenden Zünder, {name}.", sourceObjective = "Zündet 8 Raketen und 2 Raketenbündel und kehrt dann zu einer Botin des Mondfests in irgendeiner Hauptstadt zurück.", progress = "Konntet Ihr die Zünder finden, {name}?", completion = "Gut gemacht, {name}.\n\nDa Ihr jetzt in der richtigen Stimmung seid, nehmt doch diese Einladung zu dem Fest in Moonglade an.\n\nEs sind recht unterhaltsame Feierlichkeiten, falls Ihr etwas Zeit haben solltet. Wir teilen dort miteinander gutes Essen, Getränke, Geschichten und natürlich... noch mehr Feuerwerk!\n\nÖffnet die Einladung, während Ihr innerhalb des Mondlichtkreises steht und Ihr werdet nach Moonglade transportiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[8868] = { id = 8868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Segen", description = "Das Biest Omen war einstmals ein bekannter Held. Als ein Wolf von großer Stärke und Geschicklichkeit, kämpfte er im Krieg der Ahnen Seite an Seite mit den Helden dieser Zeit, bis er den dämonischen Mächten verfiel. Sein Hass richtete sich gegen seine einstigen Verbündeten und auf seinem Rachefeldzug durch Azeroth verbreitete er Tod und Verderben.\n\nLetztlich besiegte man ihn hier, in den Landen der Mondlichtung, wo er bis heute auf dem Grund des Sees von Elune'ara ruht. Doch jedes Jahr, während des Neujahrfests, erwacht er zu neuem Leben...\n\nSchart Eure Freunde um Euch! Zieht los, beschwört und besiegt das Biest Omen. Erlangt Elunes Segen!", sourceObjective = "Beschwört Omen, besiegt ihn und erlangt Elunes Segen. Kehrt anschließend zu Valadar Sternensang in Nachthafen zurück.", progress = "Tief, tief im Elune'ara See lauert Omen, {name}...", completion = "Das habt Ihr sehr gut gemacht, {name}. Der Sieg über Omen hat seinen Geist wieder in die Tiefen des Sees von Elune'ara verbannt. Obwohl das Biest durch Elune selbst gesegnet wurde und es dadurch unsterblich ist, wird sein Zorn für ein weiteres Jahr besänftigt sein.\n\nEuer Sieg ist eine Feier, {name} - eine Feier zu Ehren der Macht Omens, Eurer Stärke und der Ausdauer Eurer Verbündeten und nicht zuletzt des Friedens, den Ihr diesem tragischen Held der Vergangenheit geschenkt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8869] = { id = 8869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße Beschaulichkeit", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.", sourceObjective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8870] = { id = 8870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Mystikerviertel von Eisenschmiede. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8871] = { id = 8871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Parkviertel von Sturmwind.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8872] = { id = 8872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests in der Enklave des Cenarius in Darnassus. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8873] = { id = 8873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Tal der Weisheit in Orgrimmar. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8874] = { id = 8874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests am Eingang zur Unterstadt. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8875] = { id = 8875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests auf der Anhöhe der Ältesten in Donnerfels. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8876] = { id = 8876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Raketen", progress = "Ich hüte das Geheimnis zur Herstellung der Mondfestraketen und freue mich, mein Wissen mit den Würdigen zu teilen.\n\nIch kann Euch im Tausch gegen Münzen der Urahnen das Rezept zur Herstellung einer kleinen Rakete anbieten...", completion = "Ah, sehr schön. Hier ist Euer Rezept, {name}, möge Elune Euch segnen." }
quests[8877] = { id = 8877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zünder für Feuerwerk", progress = "Auch wenn Raketen wunderbar zum Feiern sind, so müssen sie doch von einem richtigen Zünder abgefeuert werden, damit man ihre wahre Herrlichkeit sehen kann...\n\nBringt mir Münzen der Urahnen und ich lehre Euch die Herstellung von Feuerwerkszündern, wie man sie in Moonglade sieht.", completion = "Da seid Ihr ja, {name}. Hier ist der Bauplan zur Herstellung von Feuerwerkszündern. Platziert die Zünder dort, wo Ihr feiern möchtet, und ladet Eure Freunde dazu ein!" }
quests[8878] = { id = 8878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagsrezepte", progress = "Die Kleider und Hosenanzüge, die Ihr hier sehen könnt, sind traditionelle Gewänder vergangener Zeiten. Sie werden zu Ehren alter Gebräuche und geliebter Vorfahren getragen.\n\nBringt Ihr mir Münzen der Urahnen, {name}, werde ich Euch das Muster zur Herstellung traditioneller roter Kleider oder Hosenanzüge geben.", completion = "Hier sind die Muster, {name}. Ich bin mir sicher, dass Ihr die Ergebnisse dieses Herstellungsgeheimnisses wunderschön finden werdet." }
quests[8879] = { id = 8879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Raketen", progress = "Große Festtagsraketen erhellen den Himmel sternengleich - nur die Raketenbündel können mit ihrer Schönheit rivalisieren!\n\nBringt mir Münzen der Urahnen und ich lehre Euch ihre Herstellung.", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Hier ist Euer Rezept, {name}. Verwendet sie, um Elunes Herrlichkeit zu verbreiten!" }
quests[8880] = { id = 8880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenbündel", progress = "Raketenbündel bestehen aus einer Anzahl unterschiedlicher Raketen. Ihre Schönheit ist überwältigend! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen…", completion = "Bitte sehr, {name}. Nehmt diesen Bauplan und erlernt seine Geheimnisse. Ich wünsche Euch alles Gute und freue mich schon auf Eure Kreationen!" }
quests[8881] = { id = 8881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Raketenbündel", progress = "Die Herstellung großer Raketenbündel erfordert viel Erfahrung und noch mehr Ressourcen, doch ihre Schönheit ist die Mühen wert! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen.", completion = "Vielen Dank, {name}. Hier ist der Bauplan zur Herstellung von großen Raketenbündeln. Möge Euer Feuerwerk allen Zuschauern viel Freude und Glück bereiten." }
quests[8882] = { id = 8882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zünder für Raketenbündel", progress = "Die schönsten Feuerwerke erfordern ganze Bündel an Feuerwerksraketen! Um diese abzufeuern, benötigt man Zünder für Raketenbündel! Wäre es dann nicht logisch für Euch, wenn Ihr das Geheimnis der Herstellung solcher Zünder von mir erlernen würdet? Bringt mir Münzen der Urahnen und ich werde mein Wissen mit Euch teilen…", completion = "Hier ist Euer Bauplan. Studiert ihn ausführlich und lernt…\n\nViel Glück, {name}. Mögen Eure Feuerwerke den Nachthimmel noch heller erleuchten, als die Feierlichkeiten des Mondfests selbst!" }
quests[8883] = { id = 8883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valadar Sternensang", description = "Jetzt, da Ihr in Besitz der Mondfesteinladung seid, könntet Ihr doch einmal zur Mondlichtung reisen - Ihr werdet dort viele Feiernde vorfinden! In Nachthafen erwarten Valadar Sternensang und seine Schwester Fariel bereits diejenigen, die die Feierlichkeiten kaum erwarten können.\n\nReist zur Mondlichtung mithilfe des Mondlichts und sprecht mit Valadar Sternensang; schaut Euch um und erfahrt welche Preise Ihr während des Fests gewinnen könnt!", sourceObjective = "Verwendet die Mondfesteinladung im Mondlicht und reist somit zur Mondlichtung. Sprecht nach Eurer Ankunft in Nachthafen mit Valadar Sternensang.", completion = "{name}, willkommen in Nighthaven, Gastgeber des Mondfests! Wenngleich unser Dorf normalerweise etwas entlegen und abgesondert von den Bewohner Azeroths liegt, so öffnen wir während der Festtage doch allen unsere Arme und Herzen.\n\nAmüsiert Euch gut, solange Ihr hier seid, {name}, und sprecht wieder mit mir oder meiner Schwester, wenn Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[8884] = { id = 8884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischköpfe, Fischköpfe...", description = "Seid gegrüßt, {class}. Was, frage ich Euch, könnt Ihr erkennen, wenn Ihr in Richtung Küste seht? Richtig, unser Strand... unsere Stille Küste wurde vom Übel, den Murlocs, befallen.\n\nDieser Makel darf nicht bestehen bleiben!\n\nIch habe eine Aufgabe für Euch. Solltet Ihr bereit dazu sein, so würde ich ihre Köpfe haben wollen! Mal sehen, ob wir ihre Zahl derart verringern können, dass sie nicht mehr anders können, als in die dunklen Tiefen zurückzukehren, aus denen sie gekommen sind!", sourceObjective = "Sammelt 8 Köpfe von Grimmschuppenmurlocs und bringt sie zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt.", progress = "Wir Waldläufer von der Zuflucht der Weltenwanderer haben uns der Wiedergutmachung aller Schäden gewidmet, die unser schönes Land so schrecklich verheert haben. Egal, wie lange es auch dauern mag.\n\nIch kann mich doch darauf verlassen, dass Ihr mit den Murlocköpfen zurückgekehrt seid, die ich von Euch verlangt habe?", completion = "Gute Arbeit, {class}. Dem Gestank nach zu urteilen, seid Ihr mit der von mir geforderten Beute zurückgekehrt, vielleicht sogar mit mehr. Ich bin mir sicher, dass wir dafür Verwendung haben werden, sei es in einem Eintopf oder etwas Ähnlichem.\n\nLeider scheinen Eure Bemühungen den Zweck nicht erfüllt zu haben; die Murlocs ziehen sich noch immer nicht zurück. Wir müssen noch tatkräftiger handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[8885] = { id = 8885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mmmrrrgggllls Ring", description = "Die Grimmschuppenmurlocs haben sich durch Eure Taten nicht vertreiben lassen. Ich glaube aber zu wissen, was sie endlich in die Flucht schlagen wird, und wie ich mich gleichzeitig persönlich an ihnen rächen kann.\n\nSie haben einen Murlochäuptling, der sich selbst Mmmrrrggglll nennt. Er wandert entlang des Goldenen Strandes südlich der Flussmündung umher. Dies Biest hat einst einen meiner Kameraden getötet und trägt seitdem seinen Ring als offenes Zeichen der Verachtung und des Spotts.\n\nVernichtet Mmmrrrggglll und bringt mir den Ring meines Freundes wieder. Das sollte diese Monster ein für alle Mal einschüchtern!", sourceObjective = "Erlangt Mmmrrrgggllls Ring von dem Häuptling der Grimmschuppen und kehrt damit anschließend zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt, zurück.", progress = "Ihr verhelft mir zu Erfolg und Rache, {class}. Habt Ihr den Ring?", completion = "Endlich! Die Grimmschuppen sind zwar noch immer nicht gewichen, wie erhofft, aber es war ein herrliches Schauspiel, als sie nach dem Tod ihres Anführers in Panik und Verwirrung umhergeirrt sind. Ihr habt meinen Dank und den der Sin'dorei von Silbermond!\n\nBitte, nehmt eine dieser Belohnungen für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8886] = { id = 8886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piraten der Grimmschuppen!", description = "Wie gut, dass Ihr hier seid, {class}! Diese schleimigen Grimmschuppenmurlocs haben meine Fracht gestohlen! Als wenn es nicht schon schlimm genug wäre, dass die Getriebenen mir meine letzten magischen Güter geraubt haben - und jetzt das! Was ist nur aus diesem Land geworden?\n\nKönnt Ihr mir meine Fracht wiederbeschaffen? Ich erwarte zwar nicht, dass Ihr alles zurückerlangt, bin aber für jedes Stück dankbar. Es waren die Grimmschuppenmurlocs in den Hütten im Westen, südlich des Ankerplatzes am Goldenen Strand. Ich bin mir ganz sicher!", sourceObjective = "Erlangt 6 Stücke von Kapitänin Kelisendras Fracht wieder und bringt sie zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", progress = "Ich bin dankbar für die Unterstützung von jemandem wie Euch, {name}. Es stimmt mich fast schon wieder fröhlich. Allerdings erinnert es mich auch daran, was diese Monster meinem Schiff angetan haben und was mit Quel'Thalas geschieht.\n\nHabt Ihr es geschafft, Teile meiner Fracht wiederzuerlangen?", completion = "Ihr habt es geschafft! Ihr habt mich vor dem Ruin bewahrt und die scheußlichen Kreaturen meine Vergeltung spüren lassen!\n\nWenn ich es jetzt noch schaffe, dass mir diese hübschen Waldläufer mit meiner Fracht helfen, dann komme ich endlich weg von hier! Ich muss noch einmal zurückkehren, wenn Velendris die Schiffswerft zurückerobert hat.\n\nHier, nehmt diese Münze. Ich kann Euch leider nicht mehr geben, aber ich hoffe es entlohnt Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8887] = { id = 8887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitänin Kelisendras verlorene Seekarten", description = "Interessant... was Ihr hier gefunden habt, ist eine wasserdichte Lederhülse, die ein paar Seiten Pergamentpapier enthält. Nach den Kennzeichnungen zu urteilen, handelt es sich eindeutig um Seekarten. Jede dieser Karten trägt das Siegel von Kapitänin Kelisendra.\n\nIhr habt sicher schon von einem kleinen, befestigten Lager östlich des nahegelegenen Ankerplatzes der Sonnensegel gehört. Vielleicht findet Ihr die Kapitänin ja dort?", sourceObjective = "Bringt Kapitänin Kelisendras verlorene Seekarten zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", progress = "Hallo, {class}, Euer Anblick ist ein gutes Zeichen. Ich weiß, es ist verrückt, dass ich überhaupt hier bin, wo der Ankerplatz doch von den Getriebenen überfallen wurde. Velendris und seine Waldläufer haben geschworen mich zu beschützen, unter der Bedingung, dass ich von hier verschwinde, sobald ich meine Fracht wiedererlangt habe.\n\nWas habt Ihr da... das kommt mir so bekannt vor?", completion = "Oh, Ihr herzensguter, herzensguter {class}! Ich hatte ja keine Ahnung, dass diese widerlichen Grimmschuppenmurlocs auch noch meine Seekarten entwendet hatten! Ohne diese Karten hätte ich niemals wieder in See stechen können, sobald wir den Ankerplatz zurückerobert und das Schiff repariert haben.\n\nIch bin Euch zutiefst dankbar! Hier, nehmt diese Münze als Zeichen meiner Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[8888] = { id = 8888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Magisters", description = "{class}, hört Euch mein Anliegen an. Auf Grund von Dingen, die ich jetzt nicht weiter erklären kann, habe ich beschlossen, meine nahegelegene Schule zu schließen. Vor ein paar Tagen habe ich eine meiner Schülerinnen, Lehrling Loralthalis, mit diesem Auftrag dorthin geschickt. Seitdem habe ich nichts mehr von ihr gehört.\n\nWerdet Ihr zum Nachtschimmerturm gehen und nachsehen, ob alles mit ihr in Ordnung ist? Ihr werdet den Turm finden, indem Ihr dem Pfad, der von der Zuflucht der Weltenwanderer aus nach Norden führt, folgt und dann bei der Weggabelung rechts abbiegt.", sourceObjective = "Sprecht mit Lehrling Loralthalis nahe des Nachtschimmerturms im Immersangwald.", completion = "Der Magister sorgt sich um mein Wohlergehen? Wie süß von ihm; ich wünschte er hätte ein derartiges Interesse etwas früher gezeigt, als wir noch im Turm waren.\n\nNaja, das tut jetzt nichts zur Sache. Hört gut zu, {class}, ich muss Euch um einen Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8889] = { id = 8889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deaktivierung des Turms", description = "Wie Ihr wisst, hat mich Magister Nachtschimmer hierher zurückgeschickt, damit ich die Kraftquellen, die den Turm versorgen, deaktiviere. Es gibt drei davon, sie befinden sich an unterschiedlichen Stellen im Innern des Turms.\n\nUnglücklicherweise scheine ich zu spät zu sein, denn der Nachtschimmerturm wurde von seltsamen, magischen Kreaturen überrannt. Ich habe nicht das benötigte Wissen, um diese Aufgabe zu erfüllen, aber <ein/eine:c> {class} wie Ihr, könnte es doch sicherlich ohne größere Probleme?", sourceObjective = "Deaktiviert 3 Kraftquellen des Nachtschimmerturms im Nachtschimmerturm. Bringt anschließend das Deaktivierungsjuwel zu Lehrling Loralthalis im Immersangwald.", progress = "Ich kann es aus dieser Entfernung nicht mit Sicherheit sagen... habt Ihr den Nachtschimmerturm bereits deaktiviert?", completion = "Ich bin Euch für Eure Hilfe dankbar, aber es betrübt mich zu hören, dass einige meiner Lehrlingsfreunde der Abhängigkeit verfallen sind.\n\nJetzt, da die Kraftquellen des Turms deaktiviert wurden, werde ich wohl noch eine Weile hier bleiben. Ich möchte sehen, ob sich die Lage beruhigt, damit ich mich hineinschleichen kann, um ihre Überreste zu bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8890] = { id = 8890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Turm", description = "{name}, ich hätte noch eine letzte Bitte an Euch. Würdet Ihr Magister Nachtschimmer bei der Zuflucht der Weltenwanderer über die Ereignisse berichten, die hier vorgefallen sind? Sagt ihm, dass es mir gut geht, aber betont bitte auch, dass einige Lehrlinge zu Getriebenen geworden sind.\n\nVielen Dank für Eure Hilfe!", sourceObjective = "Kehrt zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.", completion = "Nein! Ich war zu spät. Es ist alles meine Schuld.\n\nMeine Untersuchungen hinsichtlich der Aufbereitung alternativer Magiequellen sind mir außer Kontrolle geraten und ich konnte nichts mehr tun, was dies hätte aufhalten können. Wäre ich nur selbst gegangen... oder hätten sie auf mich gehört und meine Warnungen befolgt!\n\nMeine Hände sind mit Blut befleckt, {class}. Ich danke Euch dennoch, dass Ihr diese armen Seelen meiner ehemaligen Lehrlinge erlöst habt. Es ist ein kleiner Trost zu wissen, dass sie nicht länger in dem Zustand verweilen müssen, an dessen Stelle ein {race} besser tot wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[8891] = { id = 8891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgegebene Untersuchungen", description = "Ihr habt ein Buch mit Untersuchungsberichten gefunden, dass offenbar von Magister Nachtschimmer zurückgelassen wurde. Ihr überfliegt rasch den Inhalt und stellt mit Entsetzen fest, dass man versucht hat, verderbte magische Ströme zu filtern, was womöglich eine Erklärung für die Ereignisse hier beim Nachtschimmerturm sein könnte. Der Magister möchte dies sicherlich zurück.", sourceObjective = "Bringt Magister Nachtschimmers Tagebuch zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.", progress = "Was ist das? Es kommt mir bekannt vor. Oh nein, dieses Tagebuch... meine Untersuchungen... dies hat all die schrecklichen Ereignisse verursacht.", completion = "Hier ist er also, {name}, der Beweis für mein Verbrechen. Dieses Tagebuch enthält all meine missinterpretierten Studien.\n\nIch schenkte den Warnungen keine Beachtung und führte meine Untersuchungen fort, bis es schon fast zu spät war. Als ich endlich meine Fehler einsah, tat ich alles in meiner Macht stehende. Allerdings sind einige meiner Schüler zu diesem Zeitpunkt bereits zu weit gegangen. Ich evakuierte den Turm, um sie vor der Verderbnis in Schutz zu bringen. Jedoch vergaß ich in meiner Eile, die Kraftquellen zu deaktivieren.\n\nIch werde diese Aufzeichnungen verbrennen, damit sie zukünftig keinen Schaden mehr anrichten können. Ich wollte den Sin'dorei doch nur helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8892] = { id = 8892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorfall beim Ankerplatz der Sonnensegel", description = "Der Ankerplatz der Sonnensegel wurde von einem Haufen Getriebener überrannt. Sobald wir Verstärkung erhalten, werden wir diesen Verbrechern schon zeigen, wer hier das Sagen hat, {name}.\n\nIn der Zwischenzeit könntet Ihr uns helfen, indem Ihr ihnen etwas Disziplin beibringt. Geht zu ihnen und macht deutlich, dass man mit uns keine Spielchen treibt. Der Ankerplatz der Sonnensegel liegt genau westlich von Morgenluft.", sourceObjective = "Tötet 5 getriebene Rohlinge und 5 getriebene Straßendiebe und erstattet Waldläufer Degolien im Immersangwald Bericht.", completion = "Das wird ihnen zeigen, dass man es sich mit uns besser nicht verscherzt. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8893] = { id = 8893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Super-Ei-o-Mat", progress = "Der Super-Ei-O-Mat ist die neueste Erfindung von Curgle Cranklehop. Es ist eine ziemlich beeindruckende Maschine.\n\nDer Super-Ei-O-Mat fängt wild an zu spucken und zu zischen, als Ihr Euch der Steuerkonsole nähert.", completion = "Ihr legt das Hippogryphen-Ei in die Maschine. Es folgen eine Reihe von Pieptönen sowie ein seltsames Rasseln, Rattern und Klicken.\n\nEs scheint, als hätte das Ei-O-Meter Euer Ei gewogen, vermessen und verpackt. Das ist echt ein zügiger Service!" }
quests[8894] = { id = 8894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Grunds", description = "Ich kann Euch sagen, es ist furchtbar! Seltsame Dinge gehen im Turm vor sich, der Magister und seine Lehrlinge sind weggelaufen und wie Ihr wisst, wurde der gesamte Grund von magischen Bestien überrannt! Und wer sagte Wyllithen Bescheid? Niemand, so sieht es aus!\n\n{class}, Ihr müsst mir helfen, hier wieder für Ordnung zu sorgen... ich kann nicht länger über den Grund wachen, solange diese 'Anomalien' hier in blinder Wut herumlaufen!", sourceObjective = "Tötet 6 Manaschlangen und 6 Ätherbestien. Kehrt anschließend zu Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald zurück.", completion = "Nun, ich denke das dürfte fürs Erste genügen, oder nicht? Danke für die Hilfe, {class}. Ich hoffe nur, dass ich hier alles rechtzeitig absichern kann, bevor der Magister zum Nachtschimmerturm zurückkommt.\n\nNehmt dies bisschen Kleingeld; es ist nicht viel, aber ich habe im Moment nicht mehr. Ihr könnt ruhig noch ein paar Bestien mehr töten, wenn Ihr hier unterwegs seid, das wäre nett von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8895] = { id = 8895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an das Sanktum des Nordens", description = "Es freut mich, dass Ihr Euch zumindest in gewissen Hinsichten als fähig erweist, {name}. Ich gebe Euch eine weitere Aufgabe, da Ihr so begierig scheint, Euch beweisen zu wollen.\n\nDies ist ein Brief für Leybewahrer Caidanis, der Arkanist, der für die Aufrechterhaltung des Sanktums des Nordens verantwortlich ist. Geht vom Falkenplatz Richtung Südwesten und Ihr werdet ihn finden. Er ist eine sehr wichtige Persönlichkeit, ich hoffe also, dass Ihr ihn nicht mit zu belanglosem Geschwätz belästigt.", sourceObjective = "Überbringt den unbeschrifteten Brief an Leybewahrer Caidanis beim Sanktum des Nordens im Immersangwald.", progress = "Ja, {class}?", completion = "Vielen Dank, {name}. Ich habe diesen Brief bereits erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8896] = { id = 8896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwergenspion", description = "Seid Ihr sicher, dass Ihr diese Notizen bei einer Nachtelfe gefunden habt? Das meiste davon wurde in Zwergisch verfasst...\n\nAusgrabungsleiter Ambossel! Er wurde von Eisenschmiede wegen eines diplomatischen Auftrags hierher geschickt. Ich hätte es wissen müssen, sein Interesse an unseren arkanen Sankten war etwas zu groß. {name}, findet den Zwerg im Sanktum des Nordens und kümmert Euch um ihn. Oh, bitte geht diskret dabei vor.", sourceObjective = "Findet und tötet Ausgrabungsleiter Ambossel im Sanktum des Nordens und berichtet anschließend Aeldon Sonnenmal im Immersangwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[8897] = { id = 8897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Wenn ich das Tor bewache muss ich ständig an meine geliebte Colara denken. Ich kann sie immer nur für ein paar kurze Stunden sehen, wenn ich Glück habe. Ach, seht mich doch an. Ich erhalte nur einen niederen Offizierssold und jeden Tag könnte ich an die Front abberufen werden.\n\nWürde sie mich dann einfach vergessen? Ich meine, es gibt so viele wohlhabende Männer in der Stadt.\n\nHier, ich habe einige Dinge aufgeschrieben... Nicht viel, aber vielleicht könntet Ihr diese Nachricht meiner Liebsten überbringen. Mein Dank wäre Euch gewiss.", sourceObjective = "Bringt Leutnant Heldrics sorgfältig verfasste Notiz zu Colara Dean außerhalb der Bank von Sturmwind.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Oh, ist das nicht süß! Es ist das erste Mal, dass er mir überhaupt etwas schickt. Glaubt Ihr, er meint es ernst?\n\nColara Heldric? Das hat etwas Klangvolles, findet Ihr nicht? Oh, vielleicht bin ich etwas zu voreilig. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[8898] = { id = 8898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Als ich geschäftlich mit der Bank in Sturmwind zu tun hatte, traf ich ein Mädchen. Sie hat mir auf Anhieb mein Herz gestohlen. Ich kann einfach nicht mehr aufhören, an sie zu denken! Ich würde Ihr gerne diese Nachricht schicken. Ganze Zwölfmal musste ich sie neu schreiben!\n\nJetzt möchte ich sicherstellen, dass sie meinen Brief auch erhält.\n\nVielleicht reist Ihr ja nach Sturmwind und könnt mir weiterhelfen?", sourceObjective = "Bringt den zerknitterten Brief zu Colara Dean außerhalb der Bank in Sturmwind.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Tormek? Oh ja, ich erinnere mich an ihn. Er hatte einen sehr gepflegten Bart und obendrein ein recht ansehnliches Lächeln.\n\nIch kann es kaum fassen, dass er sich noch an mich erinnert!", sourceObjectiveStatus = "unverified-source-field" }
quests[8899] = { id = 8899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Wie soll ich ihre Schönheit nur beschreiben? Tausende Jahre voll der Poesie und mir fehlen die Worte.\n\nDiese Sterblichen verwässern den Geist und am Ende bleiben wir als plappernde Narren zurück.\n\nZu lange habe ich diese Worte immer und immer wieder in mich aufgenommen. Es ist mir unmöglich, sie weiter zu verfeinern. Nein, sie muss diese Nachricht noch heute erhalten, oder ein anderer Verehrer wird sie für sich einnehmen.", sourceObjective = "Bringt den makellosen Brief zu Colara Dean außerhalb der Bank von Sturmwind.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Ich habe noch nie etwas Derartiges erhalten. Wie liebenswert!", sourceObjectiveStatus = "unverified-source-field" }
quests[8900] = { id = 8900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Sie war so traurig. Ich habe es genau gespürt, trotz Ihrer Versuche es zu verbergen. Ich meine, sie wirkte so traurig, versteht Ihr?\n\nDa war diese Verbindung zwischen uns beiden, als ich mit ihr sprach. Niemand hatte mich bisher verstanden, doch sie tat es auf Anhieb.\n\nAls ich es den anderen erzählte, lachten sie nur über mich und so habe ich nie wieder mit ihr gesprochen. Doch ich vermisse sie. Würdet Ihr mir einen Gefallen tun und ihr diesen Brief von mir geben? Ich will sicher sein, dass sie ihn auch erhält.", sourceObjective = "Bringt die leicht zerknitterte Notiz zu Elenia Haydon nahe der Bank in Unterstadt.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Man mag es kaum glauben, dass ein Orc derart wortgewandt sein kann. Natürlich hatten wir bisher kaum Chancen, die Orcs im Allgemeinen besser kennenzulernen. Vielen Dank, für das Überbringen dieses Briefs.", sourceObjectiveStatus = "unverified-source-field" }
quests[8901] = { id = 8901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Habt Ihr jemals wahre Liebe erfahren, <junger Herr/junge Dame>? Noch vor Kurzem war dies ein Fremdwort für mich, doch dann traf ich dieses junge Mädchen aus Unterstadt, Elenia. Es ist selten für einen Angehörigen meiner Art, sich mit den anderen Völker einzulassen, ganz besonders mit den Verlassenen.\n\nDoch jetzt sind meine Gedanken Tag und Nacht von ihr erfüllt.\n\nWäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich möchte, dass sie hierher nach Mulgore kommt. Hoffentlich sagt sie ja.", sourceObjective = "Bringt den sorgfältig verfassten Brief zu Elenia Haydon nahe der Bank in Unterstadt.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Welch liebliche Worte Temma für mich fand. Doch, soviel mich seine Verse auch bewegen, ich könnte niemals einen {race} lieben. Wir leben in verschiedenen Welten, unsere Gedanken, unser Äußeres unterscheiden sich zu sehr.\n\nEs ist gut, dass er mir diesen Brief nicht persönlich überbracht hat. Ich könnte es nicht ertragen, sein Herz auf diese Weise zu brechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8902] = { id = 8902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Zu Lebzeiten hatte ich geschworen, Elenia, meine Jugendliebe, zu meiner Frau zu nehmen. Es ist schon Jahre her, seit ich das letzte Mal an sie denken musste. Doch seit einiger Zeit beherrschen mehr und mehr Gedanken an sie meinen Verstand.\n\nObwohl es eine Ewigkeit her ist, sollte es in unser beider Leben noch etwas Raum für unsere Liebe geben.\n\nIch bin sicher, auch sie wird sich verändert haben. Sei es drum! Wäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich selbst bin zu nervös, um ihr selbst gegenüberzutreten.", sourceObjective = "Bringt den liebevoll verfassten Brief zu Elenia Haydon nahe der Bank in Unterstadt.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Dieser Brief weckt Erinnerungen an ein längst vergangenes Leben, {name}. Elenia Tor. Einst war dies mein Name, wisst Ihr. Eine wundervolle Zeremonie an den Ufern des Sees sollte es werden. Er wollte sich zur Ruhe setzen und gemeinsam wollten wir uns auf einem Bauernhof niederlassen.\n\nEs waren einfache Träume, die wir hatten.\n\nDoch wenn er mich nun sehen könnte, ich glaube kaum, dass er die alte Elenia in mir wiedererkennen würde. Nur kaltes Fleisch und ein totes Herz...", sourceObjectiveStatus = "unverified-source-field" }
quests[8903] = { id = 8903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist ungebührlich, ja ein Schandfleck, und im schlimmsten Fall eine Bedrohung für die Sicherheit der gesamten Allianz.\n\nDenkt doch nur: Was passiert, wenn sämtliche Wachen von dieser seltsamen Krankheit betroffen werden? Irgendetwas muss geschehen.\n\nGeht zu einer der Wachen hier in Sturmwind und seht, ob sie von dieser törichten Epidemie befallen wurde.", sourceObjective = "Besorgt die Karte einer Wache von Sturmwind und bringt sie zu Aristan Mottar in Sturmwind.", progress = "Waren meine Sorgen berechtigt? Stehen unsere Wachen bereits unter dem Einfluss dieser Liebeskrankheit?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8904] = { id = 8904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist abscheulich, und wenn sie erst einmal unsere Verteidigung schwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits ein Großteil unserer Bevölkerung dieses lächerlich säuselnde Verhalten an den Tag legt. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser törichten Epidemie befallen wurde.", sourceObjective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Unterstadt.", progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8905] = { id = 8905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterquell heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Eisenschmiede.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, {name}?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8906] = { id = 8906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterquell heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Deliana in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
